const mensaje = $input.item.json.message;

if (!mensaje || !mensaje.text) {
  return { json: { chatId: '', sessionKey: '', inputText: '', skip: true } };
}

const chatId = String(mensaje.chat.id);
const texto = mensaje.text.trim();

return { json: {
  chatId,
  sessionKey: chatId,
  inputText: texto,
  skip: false
} };

const BASE_URL = $env.DASHBOARD_URL;
const API_SECRET = $env.TELEGRAM_API_SECRET;

const chatId = $('PrepararMensaje').item.json.chatId;
let params = {};
try { params = JSON.parse(query); } catch(e) { params = { pin: query }; }

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE_URL}/api/telegram/autenticar`,
  headers: { 'x-api-key': API_SECRET, 'Content-Type': 'application/json' },
  body: { chatId, pin: String(params.pin ?? query) },
  json: true
});

return JSON.stringify(result);

