const BASE_URL = $env.DASHBOARD_URL;
const API_SECRET = $env.TELEGRAM_API_SECRET;

const chatId = $('PrepararMensaje').item.json.chatId;
let params = {};
try { params = JSON.parse(query); } catch(e) {}

const body = { chatId, estudianteId: params.estudianteId };
if (params.cursoNombre) body.cursoNombre = params.cursoNombre;
if (params.periodoNombre) body.periodoNombre = params.periodoNombre;

const result = await this.helpers.httpRequest({
